def taller_within(a: list[int], k: int) -> list[int]:
    n = len(a)
    if n == 0:
        return []
    order = sorted(set(a))
    rank = {v: i + 1 for i, v in enumerate(order)}
    m = len(order)
    fen = [0] * (m + 1)

    def add(i: int, delta: int) -> None:
        while i <= m:
            fen[i] += delta
            i += i & -i

    def prefix(i: int) -> int:
        s = 0
        while i > 0:
            s += fen[i]
            i -= i & -i
        return s

    res = [0] * n
    for i in range(n):
        out = i - k - 1
        if out >= 0:
            add(rank[a[out]], -1)
        r = rank[a[i]]
        res[i] = prefix(m) - prefix(r)
        add(r, 1)
    return res
